// Ouvrir le modal YouTube
function openYouTubeModal(videoId, title) {
    const modal = document.getElementById('youtubeModal');
    const iframe = document.getElementById('youtubeIframe');
    const modalContent = modal.querySelector('.youtube-modal-content');
    
    if (modal && iframe && modalContent) {
        // Afficher l'indicateur de chargement
        modalContent.classList.add('loading');
        
        // Définir la source de l'iframe
        iframe.src = `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0&modestbranding=1`;
        
        // Pause all testimonials before showing modal
        if (typeof window.pauseAllTestimonials === 'function') {
            window.pauseAllTestimonials();
        }
        
        // Afficher le modal
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
        
        // Masquer l'indicateur de chargement après un délai
        setTimeout(() => {
            modalContent.classList.remove('loading');
        }, 1000);
        
        // Écouter l'événement de chargement de l'iframe
        iframe.onload = function() {
            modalContent.classList.remove('loading');
        };
    }
}

// Fermer le modal YouTube
function closeYouTubeModal() {
    const modal = document.getElementById('youtubeModal');
    const iframe = document.getElementById('youtubeIframe');
    const modalContent = modal.querySelector('.youtube-modal-content');
    
    if (modal && iframe && modalContent) {
        // Resume all testimonials when closing modal
        if (typeof window.resumeAllTestimonials === 'function') {
            window.resumeAllTestimonials();
        }
        
        modal.classList.remove('active');
        
        // Délai pour laisser l'animation se terminer avant de supprimer la source
        setTimeout(() => {
            iframe.src = '';
            modalContent.classList.remove('loading');
        }, 300);
        
        // Vérifier s'il y a d'autres modals ouvertes avant de remettre le body en scrollable
        try {
            const modalIds = ['unifiedModal', 'skillModal', 'personModal'];
            const anyModalOpen = modalIds.some(id => {
                const el = document.getElementById(id);
                if (!el) return false;
                const display = (el.style && el.style.display) ? el.style.display : window.getComputedStyle(el).display;
                return display && display !== 'none';
            });
            
            // Seulement remettre le body en scrollable s'il n'y a plus de modals ouvertes
            if (!anyModalOpen) {
                document.body.style.overflow = '';
            }
        } catch(e) {
            // En cas d'erreur, remettre en scrollable (comportement par défaut)
            document.body.style.overflow = '';
        }
    }
}

// Basculer l'affichage de la vidéo YouTube intégrée
function toggleYouTubeEmbed(element, videoId, title) {
    const embedContainer = element.querySelector('.project-widget-youtube-single-embed');
    const thumbnail = element.querySelector('.project-widget-youtube-single-thumbnail');
    const iframe = embedContainer.querySelector('iframe');
    
    if (embedContainer.style.display === 'none') {
        // Afficher la vidéo intégrée
        iframe.src = `https://www.youtube-nocookie.com/embed/${videoId}?autoplay=1&rel=0&modestbranding=1`;
        embedContainer.style.display = 'block';
        thumbnail.style.display = 'none';
        
        // Pause all testimonials when showing video
        if (typeof window.pauseAllTestimonials === 'function') {
            window.pauseAllTestimonials();
        }
    } else {
        // Masquer la vidéo intégrée
        iframe.src = '';
        embedContainer.style.display = 'none';
        thumbnail.style.display = 'block';
        
        // Resume all testimonials when hiding video
        if (typeof window.resumeAllTestimonials === 'function') {
            window.resumeAllTestimonials();
        }
    }
}

// Fermer le modal avec la touche Échap
document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
        closeYouTubeModal();
    }
});

